const r=$input.first().json; const tot=Number(r.total)||0; const ok=Number(r.sucesso)||0;
const taxa= tot? Math.round(ok*100/tot) : 0;
const erros=(r.top_erros||[]).map(e=>`• ${e.erro} (${e.n}x)`).join('
') || '• nenhum';
let sug='Tudo dentro do esperado.';
if (tot===0) sug='Quase não houve uso: teste o GIDEON com pedidos do dia a dia para criar histórico.';
else if (taxa<95) sug='Taxa de sucesso abaixo de 95%: corrigir o erro mais frequente.';
else if (Number(r.tempo_medio_ms)>5000) sug='Respostas acima de 5 s: revisar o tamanho do contexto enviado ao modelo.';
const txt=`📊 GIDEON — relatório da semana

Pedidos: ${tot} (sucesso ${taxa}%)
Tempo médio: ${(Number(r.tempo_medio_ms)/1000).toFixed(1)} s
Custo: R$ ${Number(r.custo).toFixed(2)}
Marcados como "não útil": ${r.nao_util}
Memórias novas: ${r.memorias_novas}
Lembretes enviados: ${r.lembretes_enviados}
Tarefas abertas: ${r.tarefas_abertas}

Erros mais frequentes:
${erros}

Sugestão: ${sug}`;
return [{json:{texto:txt}}];
